// Check for low blood stock levels
const items = $input.all();
const lowBloodStock = [];

// Function to convert Google Sheets serial date (decimal number) to a JavaScript Date string
function gsDateToJSDate(serial) {
  // Serial date number is the number of days since Jan 1, 1900 (which is day 1)
  // JS Date epoch is Jan 1, 1970 (which is day 25569 in GS format)
  // The formula converts the GS serial number to milliseconds since Unix epoch
  const date = new Date(Math.round((serial - 25569) * 86400 * 1000));

  // Use toLocaleString for a readable format based on locale
  return date.toLocaleString('en-GB', { 
      day: '2-digit', 
      month: '2-digit', 
      year: 'numeric', 
      hour: '2-digit', 
      minute: '2-digit', 
      second: '2-digit' 
  });
}


for (const item of items) {
  const bloodStock = item.json;
  // Threshold per blood group, can be set in data or default to 10 units
  const threshold = bloodStock.threshold || 10;

  let lastUpdatedFormatted = bloodStock.last_updated;

  // Check if the value is a number AND looks like a Google Sheets serial date (usually > 40000)
  if (typeof bloodStock.last_updated === 'number' && bloodStock.last_updated > 40000) {
    lastUpdatedFormatted = gsDateToJSDate(bloodStock.last_updated);
  } else {
    // If it's not a serial number, assume it came through as a string already and use it as is
    lastUpdatedFormatted = bloodStock.last_updated;
  }


  if (bloodStock.quantity <= threshold) {
    lowBloodStock.push({
      blood_group: bloodStock.blood_group,
      quantity: bloodStock.quantity,
      threshold: threshold,
      last_updated: lastUpdatedFormatted, // Use the formatted date
      alert_message: `Low blood stock alert: ${bloodStock.blood_group} has only ${bloodStock.quantity} units left (threshold: ${threshold})`
    });
  }
}

return lowBloodStock.map(blood => ({ json: blood }));

